repo.shipments.py:
"""Shipment records."""


class Shipment:
    def __init__(self, route, weight):
        self.route = route
        self.weight = weight

    def __repr__(self):
        return "Shipment(%r, %r)" % (self.route, self.weight)


ROWS = [('r22', 43), ('r10', 42), ('r31', 51), ('r22', 36), ('r10', 47)]


def load_shipments():
    """Yield the stored shipments one at a time."""
    for route, weight in ROWS:
        yield Shipment(route, weight)

repo.positions.py:
"""Position windows over shipments."""


def weight_between(shipments, low, high):
    """Return the weight of the shipments at positions low to high, both included. Positions start at 1."""
    return [x.weight for x in shipments[low - 1:high - 1]]


def first_weights(shipments, n):
    """Return the weight of the first n shipments."""
    return weight_between(shipments, 1, n)


def route_names(shipments):
    """Return the distinct route values, in first-seen order."""
    names = []
    for x in shipments:
        if x.route not in names:
            names.append(x.route)
    return names

